#include <limits.h>

#define MAX_H 50
#define MAX_W 50
#define MAX_SCROLLS 5
#define INF 1000000000

typedef struct {
    int x, y;
} Point;

int H, W;
char grid[MAX_H][MAX_W+1];
int dist_to_hole[MAX_H][MAX_W];
int scroll_count;
Point scrolls[MAX_SCROLLS];
Point start, goal;

// Directions: up, down, left, right
int dx[4] = {-1, 1, 0, 0};
int dy[4] = {0, 0, -1, 1};

int min(int a, int b) { return a < b ? a : b; }

// Compute distance to nearest hole (BFS from all holes)
void compute_dist_to_hole() {
    int queue[MAX_H*MAX_W][2];
    int front = 0, rear = 0;
    int visited[MAX_H][MAX_W];
    for (int i = 0; i < H; i++)
        for (int j = 0; j < W; j++) {
            visited[i][j] = 0;
            dist_to_hole[i][j] = INF;
            if (grid[i][j] == 'H') {
                dist_to_hole[i][j] = 0;
                visited[i][j] = 1;
                queue[rear][0] = i;
                queue[rear][1] = j;
                rear++;
            }
        }
    while (front < rear) {
        int x = queue[front][0];
        int y = queue[front][1];
        front++;
        for (int d = 0; d < 4; d++) {
            int nx = x + dx[d];
            int ny = y + dy[d];
            if (nx >= 0 && nx < H && ny >= 0 && ny < W && !visited[nx][ny]) {
                visited[nx][ny] = 1;
                dist_to_hole[nx][ny] = dist_to_hole[x][y] + 1;
                queue[rear][0] = nx;
                queue[rear][1] = ny;
                rear++;
            }
        }
    }
}

// Cost to move from (x,y) to (nx,ny)
int move_cost(int x, int y, int nx, int ny) {
    // cost depends only on destination tile's distance to hole
    int d = dist_to_hole[nx][ny];
    if (d == 0) return INF; // cannot move onto hole
    if (d >= 3) return 1;
    if (d == 2) return 2;
    if (d == 1) return 3;
    return INF;
}

// Dijkstra's algorithm on state (x, y, mask)
int dp[MAX_H][MAX_W][1<<MAX_SCROLLS];

void dijkstra() {
    int total_states = H * W * (1 << scroll_count);
    int visited[MAX_H][MAX_W][1<<MAX_SCROLLS];
    for (int i = 0; i < H; i++)
        for (int j = 0; j < W; j++)
            for (int k = 0; k < (1<<scroll_count); k++) {
                dp[i][j][k] = INF;
                visited[i][j][k] = 0;
            }

    // priority queue: (cost, x, y, mask)
    // simple array-based implementation for small size (max states 50*50*32 = 80000)
    int pq_size = 0;
    int pq_cost[80000], pq_x[80000], pq_y[80000], pq_mask[80000];

    // initial state
    int start_mask = 0;
    for (int i = 0; i < scroll_count; i++) {
        if (scrolls[i].x == start.x && scrolls[i].y == start.y)
            start_mask |= (1 << i);
    }
    dp[start.x][start.y][start_mask] = 0;
    pq_cost[pq_size] = 0;
    pq_x[pq_size] = start.x;
    pq_y[pq_size] = start.y;
    pq_mask[pq_size] = start_mask;
    pq_size++;

    while (pq_size > 0) {
        // extract min (simple linear scan, small size)
        int min_idx = 0;
        for (int i = 1; i < pq_size; i++) {
            if (pq_cost[i] < pq_cost[min_idx]) min_idx = i;
        }
        int cur_cost = pq_cost[min_idx];
        int x = pq_x[min_idx];
        int y = pq_y[min_idx];
        int mask = pq_mask[min_idx];
        // remove by swapping with last
        pq_cost[min_idx] = pq_cost[pq_size-1];
        pq_x[min_idx] = pq_x[pq_size-1];
        pq_y[min_idx] = pq_y[pq_size-1];
        pq_mask[min_idx] = pq_mask[pq_size-1];
        pq_size--;

        if (visited[x][y][mask]) continue;
        visited[x][y][mask] = 1;

        for (int d = 0; d < 4; d++) {
            int nx = x + dx[d];
            int ny = y + dy[d];
            if (nx < 0 || nx >= H || ny < 0 || ny >= W) continue;
            int cost = move_cost(x, y, nx, ny);
            if (cost == INF) continue;
            int new_mask = mask;
            for (int i = 0; i < scroll_count; i++) {
                if (scrolls[i].x == nx && scrolls[i].y == ny)
                    new_mask |= (1 << i);
            }
            int new_cost = cur_cost + cost;
            if (new_cost < dp[nx][ny][new_mask]) {
                dp[nx][ny][new_mask] = new_cost;
                pq_cost[pq_size] = new_cost;
                pq_x[pq_size] = nx;
                pq_y[pq_size] = ny;
                pq_mask[pq_size] = new_mask;
                pq_size++;
            }
        }
    }
}

