#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

typedef long long ll;

typedef struct {
    int to, next;
    ll w;
} Edge;

static int dx[4] = {1, -1, 0, 0};
static int dy[4] = {0, 0, 1, -1};

int main(void) {
    int H, W;
    if (scanf("%d %d", &H, &W) != 2) return 0;

    char **g = (char **)malloc(sizeof(char *) * H);
    for (int i = 0; i < H; i++) {
        g[i] = (char *)malloc(W + 5);
        scanf("%s", g[i]);
    }

    int sx = -1, sy = -1, gx = -1, gy = -1;
    int itemCount = 0;

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (g[i][j] == 'S') {
                sx = i; sy = j;
            } else if (g[i][j] == 'G') {
                gx = i; gy = j;
            } else if (g[i][j] == 'C') {
                itemCount++;
            }
        }
    }

    int totalPoints = itemCount + 2; /* S + Cs + G */
    int *px = (int *)malloc(sizeof(int) * totalPoints);
    int *py = (int *)malloc(sizeof(int) * totalPoints);

    int idx = 0;
    px[idx] = sx; py[idx] = sy; idx++;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (g[i][j] == 'C') {
                px[idx] = i; py[idx] = j; idx++;
            }
        }
    }
    px[idx] = gx; py[idx] = gy;

    int N = H * W;

    int *cost = (int *)malloc(sizeof(int) * N);
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (g[i][j] == '#') {
                cost[i * W + j] = -1; /* hole, cannot stand */
            } else {
                int cnt = 0;
                for (int d = 0; d < 4; d++) {
                    int ni = i + dx[d], nj = j + dy[d];
                    if (0 <= ni && ni < H && 0 <= nj && nj < W && g[ni][nj] == '#') cnt++;
                }
                cost[i * W + j] = 1 + cnt;
            }
        }
    }

    int maxEdges = N * 4;
    Edge *edges = (Edge *)malloc(sizeof(Edge) * maxEdges);
    int *head = (int *)malloc(sizeof(int) * N);
    for (int i = 0; i < N; i++) head[i] = -1;
    int ecnt = 0;

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (g[i][j] == '#') continue;
            int u = i * W + j;
            for (int d = 0; d < 4; d++) {
                int ni = i + dx[d], nj = j + dy[d];
                if (0 <= ni && ni < H && 0 <= nj && nj < W && g[ni][nj] != '#') {
                    int v = ni * W + nj;
                    edges[ecnt].to = v;
                    edges[ecnt].w = cost[v]; /* cost to move onto destination tile */
                    edges[ecnt].next = head[u];
                    head[u] = ecnt++;
                }
            }
        }
    }

    ll INF = (1LL << 60);

    ll **distPts = (ll **)malloc(sizeof(ll *) * totalPoints);
    for (int i = 0; i < totalPoints; i++) {
        distPts[i] = (ll *)malloc(sizeof(ll) * totalPoints);
        for (int j = 0; j < totalPoints; j++) distPts[i][j] = INF;
    }

    ll *dist = (ll *)malloc(sizeof(ll) * N);
    char *used = (char *)malloc(sizeof(char) * N);

    for (int s = 0; s < totalPoints; s++) {
        for (int i = 0; i < N; i++) {
            dist[i] = INF;
            used[i] = 0;
        }

        int start = px[s] * W + py[s];
        dist[start] = 0;

        for (;;) {
            int v = -1;
            ll best = INF;
            for (int i = 0; i < N; i++) {
                if (!used[i] && dist[i] < best) {
                    best = dist[i];
                    v = i;
                }
            }
            if (v == -1) break;
            used[v] = 1;

            for (int e = head[v]; e != -1; e = edges[e].next) {
                int to = edges[e].to;
                ll nd = dist[v] + edges[e].w;
                if (nd < dist[to]) dist[to] = nd;
            }
        }

        for (int t = 0; t < totalPoints; t++) {
            int goal = px[t] * W + py[t];
            distPts[s][t] = dist[goal];
        }
    }

    if (itemCount == 0) {
        ll ans = distPts[0][1];
        if (ans >= INF / 2) printf("-1\n");
        else printf("%lld\n", ans);
        return 0;
    }

    int M = itemCount;
    int FULL = 1 << M;
    ll **dp = (ll **)malloc(sizeof(ll *) * FULL);
    for (int m = 0; m < FULL; m++) {
        dp[m] = (ll *)malloc(sizeof(ll) * M);
        for (int i = 0; i < M; i++) dp[m][i] = INF;
    }

    for (int i = 0; i < M; i++) {
        dp[1 << i][i] = distPts[0][i + 1];
    }

    for (int mask = 0; mask < FULL; mask++) {
        for (int last = 0; last < M; last++) {
            if (dp[mask][last] >= INF / 2) continue;
            for (int nxt = 0; nxt < M; nxt++) {
                if (mask & (1 << nxt)) continue;
                ll d = distPts[last + 1][nxt + 1];
                if (d >= INF / 2) continue;
                int nmask = mask | (1 << nxt);
                ll nd = dp[mask][last] + d;
                if (nd < dp[nmask][nxt]) dp[nmask][nxt] = nd;
            }
        }
    }

    ll ans = INF;
    for (int last = 0; last < M; last++) {
        if (dp[FULL - 1][last] >= INF / 2) continue;
        ll d = distPts[last + 1][M + 1];
        if (d >= INF / 2) continue;
        ll cand = dp[FULL - 1][last] + d;
        if (cand < ans) ans = cand;
    }

    if (ans >= INF / 2) printf("-1\n");
    else printf("%lld\n", ans);

    return 0;
}

import java.io.*;
import java.util.*;

public class Main {
    static final int[] dx = {1, -1, 0, 0};
    static final int[] dy = {0, 0, 1, -1};
    static int H, W, S;
    static char[][] grid;
    static int[][] distToHole;
    static int startX, startY, goalX, goalY;
    static List<int[]> scrolls = new ArrayList<>();

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        H = Integer.parseInt(st.nextToken());
        W = Integer.parseInt(st.nextToken());
        S = Integer.parseInt(st.nextToken());

        grid = new char[H][W];
        for (int i = 0; i < H; i++) {
            grid[i] = br.readLine().toCharArray();
        }

        // find start, goal, scrolls
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                if (grid[i][j] == 'S') {
                    startX = i; startY = j;
                } else if (grid[i][j] == 'G') {
                    goalX = i; goalY = j;
                } else if (grid[i][j] == 'T') {
                    scrolls.add(new int[]{i, j});
                }
            }
        }

        // compute distance to nearest hole
        distToHole = new int[H][W];
        for (int[] row : distToHole) Arrays.fill(row, Integer.MAX_VALUE);
        Queue<int[]> q = new ArrayDeque<>();
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                if (grid[i][j] == 'H') {
                    distToHole[i][j] = 0;
                    q.offer(new int[]{i, j});
                }
            }
        }
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int x = cur[0], y = cur[1];
            for (int d = 0; d < 4; d++) {
                int nx = x + dx[d], ny = y + dy[d];
                if (nx >= 0 && nx < H && ny >= 0 && ny < W && distToHole[nx][ny] == Integer.MAX_VALUE) {
                    distToHole[nx][ny] = distToHole[x][y] + 1;
                    q.offer(new int[]{nx, ny});
                }
            }
        }

        // Precompute move cost between any two cells (including start, goal, scrolls)
        // We'll only need costs between these special points.
        List<int[]> points = new ArrayList<>();
        points.add(new int[]{startX, startY});
        for (int[] s : scrolls) points.add(s);
        points.add(new int[]{goalX, goalY});

        int n = points.size();
        int[][] cost = new int[n][n];
        for (int i = 0; i < n; i++) {
            int[] dist = dijkstra(points.get(i)[0], points.get(i)[1]);
            for (int j = 0; j < n; j++) {
                int tx = points.get(j)[0], ty = points.get(j)[1];
                cost[i][j] = dist[tx][ty];
                if (cost[i][j] == Integer.MAX_VALUE) cost[i][j] = -1; // unreachable
            }
        }

        int scrollCount = scrolls.size();
        // DP over subsets: dp[mask][last] = min time to collect mask and end at last (index in points, 0..scrollCount)
        int INF = Integer.MAX_VALUE / 2;
        int[][] dp = new int[1 << scrollCount][scrollCount];
        for (int[] row : dp) Arrays.fill(row, INF);

        // Initialize: from start (index 0) to each scroll
        for (int i = 0; i < scrollCount; i++) {
            if (cost[0][1 + i] != -1) {
                dp[1 << i][i] = cost[0][1 + i];
            }
        }

        for (int mask = 0; mask < (1 << scrollCount); mask++) {
            for (int last = 0; last < scrollCount; last++) {
                if ((mask & (1 << last)) == 0) continue;
                if (dp[mask][last] == INF) continue;
                for (int next = 0; next < scrollCount; next++) {
                    if ((mask & (1 << next)) != 0) continue;
                    int nextMask = mask | (1 << next);
                    int c = cost[1 + last][1 + next];
                    if (c != -1 && dp[mask][last] + c < dp[nextMask][next]) {
                        dp[nextMask][next] = dp[mask][last] + c;
                    }
                }
            }
        }

        int fullMask = (1 << scrollCount) - 1;
        int answer = INF;
        if (scrollCount == 0) {
            // no scrolls, just go from start to goal
            int[] dist = dijkstra(startX, startY);
            answer = dist[goalX][goalY];
        } else {
            for (int last = 0; last < scrollCount; last++) {
                if (dp[fullMask][last] == INF) continue;
                int c = cost[1 + last][n - 1]; // to goal
                if (c != -1) {
                    answer = Math.min(answer, dp[fullMask][last] + c);
                }
            }
        }

        System.out.println(answer == INF ? -1 : answer);
    }

    static int[] dijkstra(int sx, int sy) {
        int[][] dist = new int[H][W];
        for (int[] row : dist) Arrays.fill(row, Integer.MAX_VALUE);
        PriorityQueue<int[]> pq = new PriorityQueue<>((a,b) -> a[2] - b[2]);
        dist[sx][sy] = 0;
        pq.offer(new int[]{sx, sy, 0});

        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int x = cur[0], y = cur[1], d = cur[2];
            if (d != dist[x][y]) continue;

            for (int dir = 0; dir < 4; dir++) {
                int nx = x + dx[dir], ny = y + dy[dir];
                if (nx < 0 || nx >= H || ny < 0 || ny >= W) continue;
                if (grid[nx][ny] == '#' || grid[nx][ny] == 'H') continue;

                // movement cost depends on proximity to holes
                int cost = 1;
                int dH = distToHole[nx][ny];
                if (dH == 1) cost = S;
                else if (dH == 2) cost = 2;
                // else cost = 1

                if (dist[x][y] + cost < dist[nx][ny]) {
                    dist[nx][ny] = dist[x][y] + cost;
                    pq.offer(new int[]{nx, ny, dist[nx][ny]});
                }
            }
        }
        return dist[goalX][goalY]; // We'll just return full dist array
    }
}

