    static final long INF = Long.MAX_VALUE / 4;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        while (true) {
            String first = fs.next();
            if (first == null) return;
            int W = Integer.parseInt(first);
            int H = fs.nextInt();
            if (W == 0 && H == 0) break;

            char[][] grid = new char[H][W];
            int sx = -1, sy = -1, gx = -1, gy = -1;
            List<int[]> scrolls = new ArrayList<>();
            List<int[]> holes = new ArrayList<>();

            for (int y = 0; y < H; y++) {
                String s = fs.next();
                for (int x = 0; x < W; x++) {
                    char c = s.charAt(x);
                    grid[y][x] = c;
                    if (c == 'S') {
                        sx = x; sy = y;
                    } else if (c == 'G') {
                        gx = x; gy = y;
                    } else if (c == 'C') {
                        scrolls.add(new int[]{x, y});
                    } else if (c == '#') {
                        holes.add(new int[]{x, y});
                    }
                }
            }

            int[][] cost = new int[H][W];
            for (int y = 0; y < H; y++) {
                Arrays.fill(cost[y], 1);
            }

            int[] dx8 = {-1,-1,-1,0,0,1,1,1};
            int[] dy8 = {-1,0,1,-1,1,-1,0,1};

            for (int[] h : holes) {
                int x = h[0], y = h[1];
                for (int dir = 0; dir < 8; dir++) {
                    int nx = x + dx8[dir];
                    int ny = y + dy8[dir];
                    if (0 <= nx && nx < W && 0 <= ny && ny < H && grid[ny][nx] != '#') {
                        cost[ny][nx]++;
                    }
                }
            }

            List<int[]> points = new ArrayList<>();
            points.add(new int[]{sx, sy});
            points.addAll(scrolls);
            points.add(new int[]{gx, gy});

            int n = points.size();
            long[][] distBetween = new long[n][n];
            for (int i = 0; i < n; i++) Arrays.fill(distBetween[i], INF);

            for (int i = 0; i < n; i++) {
                long[][] d = dijkstra(points.get(i)[0], points.get(i)[1], grid, cost, W, H);
                for (int j = 0; j < n; j++) {
                    int tx = points.get(j)[0], ty = points.get(j)[1];
                    distBetween[i][j] = d[ty][tx];
                }
            }

            int k = scrolls.size();
            if (k == 0) {
                long ans = distBetween[0][1];
                System.out.println(ans >= INF ? -1 : ans);
                continue;
            }

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (distBetween[i][j] >= INF) {
                        // If any required move is impossible, DP will naturally fail,
                        // so no need to stop here.
                    }
                }
            }

            int full = 1 << k;
            long[][] dp = new long[full][k];
            for (int i = 0; i < full; i++) Arrays.fill(dp[i], INF);

            for (int i = 0; i < k; i++) {
                dp[1 << i][i] = distBetween[0][1 + i];
            }

            for (int mask = 0; mask < full; mask++) {
                for (int last = 0; last < k; last++) {
                    long cur = dp[mask][last];
                    if (cur >= INF) continue;
                    for (int nxt = 0; nxt < k; nxt++) {
                        if ((mask & (1 << nxt)) != 0) continue;
                        long w = distBetween[1 + last][1 + nxt];
                        if (w >= INF) continue;
                        int nmask = mask | (1 << nxt);
                        if (dp[nmask][nxt] > cur + w) {
                            dp[nmask][nxt] = cur + w;
                        }
                    }
                }
            }

            long ans = INF;
            int all = full - 1;
            for (int last = 0; last < k; last++) {
                long cur = dp[all][last];
                long w = distBetween[1 + last][1 + k];
                if (cur < INF && w < INF) {
                    ans = Math.min(ans, cur + w);
                }
            }

            System.out.println(ans >= INF ? -1 : ans);
        }
    }

    static long[][] dijkstra(int sx, int sy, char[][] grid, int[][] cost, int W, int H) {
        long[][] dist = new long[H][W];
        for (int y = 0; y < H; y++) Arrays.fill(dist[y], INF);

        PriorityQueue<Node> pq = new PriorityQueue<>();
        dist[sy][sx] = 0;
        pq.add(new Node(sy * W + sx, 0));

        int[] dx4 = {1, -1, 0, 0};
        int[] dy4 = {0, 0, 1, -1};

        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            int v = cur.v;
            int x = v % W;
            int y = v / W;
            if (cur.d != dist[y][x]) continue;

            for (int dir = 0; dir < 4; dir++) {
                int nx = x + dx4[dir];
                int ny = y + dy4[dir];
                if (nx < 0 || nx >= W || ny < 0 || ny >= H) continue;
                if (grid[ny][nx] == '#') continue;

                long nd = cur.d + cost[ny][nx];
                if (nd < dist[ny][nx]) {
                    dist[ny][nx] = nd;
                    pq.add(new Node(ny * W + nx, nd));
                }
            }
        }

        return dist;
    }
}

