            } else if (grid[i][j] == 'G') {
                goal_r = i;
                goal_c = j;
            } else if (grid[i][j] == 'S') {
                scrolls.push_back({i, j});
            } else if (grid[i][j] == 'H') {
                holes.push_back({i, j});
            }
        }
    }

    int dr[] = {-1, 1, 0, 0};
    int dc[] = {0, 0, -1, 1};

    // Precompute cost for each cell
    vector<vector<int>> cost(H, vector<int>(W, 1));
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (grid[i][j] == '#') continue;
            int cnt = 0;
            for (int d = 0; d < 4; d++) {
                int ni = i + dr[d];
                int nj = j + dc[d];
                if (ni >= 0 && ni < H && nj >= 0 && nj < W && grid[ni][nj] == 'H') {
                    cnt++;
                }
            }
            if (cnt > 0) cost[i][j] = cnt + 1;
        }
    }

    // For holes themselves, cost is irrelevant since we can't step on them
    for (auto [r, c] : holes) {
        cost[r][c] = INF;
    }

    // For walls
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (grid[i][j] == '#') {
                cost[i][j] = INF;
            }
        }
    }

    int S = scrolls.size();
    // Add goal and start to the list of important points
    // We'll compute distances between all important points
    vector<pair<int,int>> points;
    points.push_back({start_r, start_c});
    for (auto [r, c] : scrolls) {
        points.push_back({r, c});
    }
    points.push_back({goal_r, goal_c});

    int N = points.size();
    vector<vector<int>> dist(N, vector<int>(N, INF));

    // Dijkstra from each important point
    for (int i = 0; i < N; i++) {
        auto [sr, sc] = points[i];
        vector<vector<int>> d(H, vector<int>(W, INF));
        priority_queue<pair<int,pair<int,int>>, vector<pair<int,pair<int,int>>>, greater<>> pq;
        d[sr][sc] = 0;
        pq.push({0, {sr, sc}});

        while (!pq.empty()) {
            auto [cur_dist, pos] = pq.top();
            pq.pop();
            int r = pos.first, c = pos.second;
            if (cur_dist > d[r][c]) continue;

            for (int dir = 0; dir < 4; dir++) {
                int nr = r + dr[dir];
                int nc = c + dc[dir];
                if (nr >= 0 && nr < H && nc >= 0 && nc < W && grid[nr][nc] != '#') {
                    int nd = cur_dist + cost[nr][nc];
                    if (nd < d[nr][nc]) {
                        d[nr][nc] = nd;
                        pq.push({nd, {nr, nc}});
                    }
                }
            }
        }

        for (int j = 0; j < N; j++) {
            auto [tr, tc] = points[j];
            dist[i][j] = d[tr][tc];
        }
    }

    // DP over subsets of scrolls
    // dp[mask][last] = min time to collect scrolls in mask and end at point 'last'
    // last: 0 = start, 1..S = scrolls, S+1 = goal
    // We need to start from start (index 0), collect all scrolls, and end at goal (index N-1 = S+1)

    vector<vector<int>> dp(1 << S, vector<int>(S + 2, INF));
    dp[0][0] = 0;  // Start at start point

    for (int mask = 0; mask < (1 << S); mask++) {
        for (int last = 0; last <= S; last++) {
            if (dp[mask][last] == INF) continue;
            int from_idx;
            if (last == 0) from_idx = 0;
            else from_idx = last;  // scroll index in points array

            // Try to go to next scroll
            for (int next = 0; next < S; next++) {
                if (mask & (1 << next)) continue;
                int to_idx = next + 1;  // +1 because index 0 is start
                int nd = dp[mask][last] + dist[from_idx][to_idx];
                if (nd < dp[mask | (1 << next)][next + 1]) {
                    dp[mask | (1 << next)][next + 1] = nd;
                }
            }
        }
    }

    // Now from each final scroll state, go to goal
    int ans = INF;
    int goal_idx = N - 1;
    for (int last = 1; last <= S; last++) {
        int from_idx = last;
        if (dp[(1 << S) - 1][last] != INF) {
            ans = min(ans, dp[(1 << S) - 1][last] + dist[from_idx][goal_idx]);
        }
    }

    // Also consider direct path from start to goal if no scrolls
    if (S == 0) {
        ans = dist[0][goal_idx];
    }

    cout << ans << "\n";

    return 0;
}

