static const long long INF = (1LL << 60);

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W;
    cin >> H >> W;
    vector<string> S(H);
    for (int i = 0; i < H; i++) cin >> S[i];

    vector<pair<int,int>> items; // scrolls
    pair<int,int> start = {-1, -1}, goal = {-1, -1};

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (S[i][j] == 'S') start = {i, j};
            else if (S[i][j] == 'G') goal = {i, j};
            else if (S[i][j] == '*') items.push_back({i, j});
        }
    }

    int K = (int)items.size();

    // Cost to enter each tile:
    // hole '#' is impassable
    // otherwise cost = 1 + number of adjacent holes
    vector<vector<int>> enterCost(H, vector<int>(W, -1));
    int di[4] = {-1, 1, 0, 0};
    int dj[4] = {0, 0, -1, 1};

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (S[i][j] == '#') continue;
            int c = 1;
            for (int d = 0; d < 4; d++) {
                int ni = i + di[d], nj = j + dj[d];
                if (0 <= ni && ni < H && 0 <= nj && nj < W && S[ni][nj] == '#') c++;
            }
            enterCost[i][j] = c;
        }
    }

    vector<pair<int,int>> special;
    special.push_back(start);
    for (auto &p : items) special.push_back(p);
    special.push_back(goal);

    int M = K + 2; // start + items + goal

    auto dijkstra = [&](pair<int,int> src) {
        vector<vector<long long>> dist(H, vector<long long>(W, INF));
        priority_queue<
            pair<long long, pair<int,int>>,
            vector<pair<long long, pair<int,int>>>,
            greater<pair<long long, pair<int,int>>>
        > pq;

        dist[src.first][src.second] = 0;
        pq.push({0, src});

        while (!pq.empty()) {
            auto cur = pq.top(); pq.pop();
            long long cd = cur.first;
            int i = cur.second.first;
            int j = cur.second.second;
            if (cd != dist[i][j]) continue;

            for (int d = 0; d < 4; d++) {
                int ni = i + di[d], nj = j + dj[d];
                if (ni < 0 || ni >= H || nj < 0 || nj >= W) continue;
                if (S[ni][nj] == '#') continue;
                long long nd = cd + enterCost[ni][nj];
                if (nd < dist[ni][nj]) {
                    dist[ni][nj] = nd;
                    pq.push({nd, {ni, nj}});
                }
            }
        }
        return dist;
    };

    vector<vector<long long>> sp(M, vector<long long>(M, INF));
    for (int i = 0; i < M; i++) {
        auto dist = dijkstra(special[i]);
        for (int j = 0; j < M; j++) {
            sp[i][j] = dist[special[j].first][special[j].second];
        }
    }

    // If any required point is unreachable, answer is -1
    for (int i = 0; i < M; i++) {
        bool ok = false;
        for (int j = 0; j < M; j++) {
            if (i == j || sp[i][j] < INF) ok = true;
        }
        if (!ok) {
            cout << -1 << '\n';
            return 0;
        }
    }

    // DP over subsets of scrolls
    // special indices: 0 = start, 1..K = scrolls, K+1 = goal
    if (K == 0) {
        long long ans = sp[0][1];
        cout << (ans >= INF ? -1 : ans) << '\n';
        return 0;
    }

    int FULL = 1 << K;
    vector<vector<long long>> dp(FULL, vector<long long>(K, INF));

    for (int i = 0; i < K; i++) {
        dp[1 << i][i] = sp[0][i + 1];
    }

    for (int mask = 0; mask < FULL; mask++) {
        for (int last = 0; last < K; last++) {
            if (dp[mask][last] >= INF) continue;
            for (int nxt = 0; nxt < K; nxt++) {
                if (mask & (1 << nxt)) continue;
                long long w = sp[last + 1][nxt + 1];
                if (w >= INF) continue;
                int nmask = mask | (1 << nxt);
                dp[nmask][nxt] = min(dp[nmask][nxt], dp[mask][last] + w);
            }
        }
    }

    long long ans = INF;
    for (int last = 0; last < K; last++) {
        if (dp[FULL - 1][last] >= INF) continue;
        long long w = sp[last + 1][K + 1];
        if (w >= INF) continue;
        ans = min(ans, dp[FULL - 1][last] + w);
    }

    cout << (ans >= INF ? -1 : ans) << '\n';
    return 0;
}

