    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'G':
                goal = (i, j)

    # First, compute hole proximity for each cell
    # 0 = hole, 1 = adjacent to 1 hole, 2 = adjacent to 2 holes, etc.
    cost_map = [[0] * W for _ in range(H)]

    # Find all holes
    holes = []
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'H':
                holes.append((i, j))

    # For each non-hole cell, count adjacent holes
    directions = [(-1,0), (1,0), (0,-1), (0,1)]
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'H':
                cost_map[i][j] = -1  # impassable
            else:
                hole_count = 0
                for dy, dx in directions:
                    ny, nx = i + dy, j + dx
                    if 0 <= ny < H and 0 <= nx < W and grid[ny][nx] == 'H':
                        hole_count += 1
                cost_map[i][j] = hole_count + 1  # +1 because moving to a tile with 0 adjacent holes costs 1

    # BFS to find shortest path between any two points
    def bfs(start_y, start_x):
        dist = [[-1] * W for _ in range(H)]
        dq = deque()
        dist[start_y][start_x] = 0
        dq.append((start_y, start_x))

        while dq:
            y, x = dq.popleft()
            for dy, dx in directions:
                ny, nx = y + dy, x + dx
                if 0 <= ny < H and 0 <= nx < W and dist[ny][nx] == -1 and cost_map[ny][nx] != -1:
                    dist[ny][nx] = dist[y][x] + cost_map[ny][nx]
                    dq.append((ny, nx))
        return dist

    # Get distances from start, goal, and all scrolls
    points = [start] + scrolls + [goal]
    point_names = ['S'] + [f'Scroll_{i}' for i in range(N)] + ['G']

    # Compute distance matrix
    M = N + 2  # start + N scrolls + goal
    dist_matrix = [[-1] * M for _ in range(M)]

    for i in range(M):
        d = bfs(points[i][0], points[i][1])
        for j in range(M):
            if i != j:
                dist_matrix[i][j] = d[points[j][0]][points[j][1]]

    # Check if all paths exist
    for i in range(M):
        for j in range(M):
            if i != j and dist_matrix[i][j] == -1:
                print(-1)
                return

    # TSP: start at index 0 (S), visit all scrolls (1 to N), end at index M-1 (G)
    # We need to visit all scrolls, order doesn't matter
    scroll_indices = list(range(1, N + 1))

    if N == 0:
        print(dist_matrix[0][M-1])
        return

    min_time = float('inf')

    # Try all permutations of scroll visits
    for perm in itertools.permutations(scroll_indices):
        total = 0
        current = 0  # start
        for scroll_idx in perm:
            total += dist_matrix[current][scroll_idx]
            current = scroll_idx
        total += dist_matrix[current][M-1]  # to goal
        min_time = min(min_time, total)

    print(min_time)

