        if not line:
            continue
        W, H = map(int, line.split())
        if W == 0 and H == 0:
            break

        grid = []
        for i in range(H):
            grid.append(input_data[idx])
            idx += 1

        holes = []
        start = None
        goal = None
        scrolls = []

        for r in range(H):
            for c in range(len(grid[r])):
                ch = grid[r][c]
                if ch == 'X':
                    holes.append((r, c))
                elif ch == 'S':
                    start = (r, c)
                elif ch == 'G':
                    goal = (r, c)
                elif ch == 'o':
                    scrolls.append((r, c))

        # BFS to compute min distance to nearest hole
        dist_to_hole = [[float('inf')] * W for _ in range(H)]
        q = deque()
        for (r, c) in holes:
            dist_to_hole[r][c] = 0
            q.append((r, c))

        while q:
            r, c = q.popleft()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < H and 0 <= nc < W and dist_to_hole[nr][nc] == float('inf'):
                    dist_to_hole[nr][nc] = dist_to_hole[r][c] + 1
                    q.append((nr, nc))

        def move_cost(r, c):
            d = dist_to_hole[r][c]
            if d == 0: return float('inf')
            elif d == 1: return 3
            elif d == 2: return 2
            else: return 1

        def dijkstra(sr, sc):
            dist = [[float('inf')] * W for _ in range(H)]
            dist[sr][sc] = 0
            pq = [(0, sr, sc)]
            while pq:
                cost, r, c = heapq.heappop(pq)
                if cost > dist[r][c]: continue
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < H and 0 <= nc < W:
                        nc_cost = cost + move_cost(nr, nc)
                        if nc_cost < dist[nr][nc]:
                            dist[nr][nc] = nc_cost
                            heapq.heappush(pq, (nc_cost, nr, nc))
            return dist

        key_points = [start] + scrolls + [goal]
        n = len(key_points)
        dists = []
        for p in key_points:
            dists.append(dijkstra(p[0], p[1]))

        def d(i, j):
            r, c = key_points[j]
            return dists[i][r][c]

        ns = len(scrolls)
        INF = float('inf')
        # TSP: collect all scrolls (indices 1..ns) then reach goal (index ns+1)
        dp = [[INF] * (1 << ns) for _ in range(ns + 1)]
        dp[0][0] = 0  # at start, no scrolls collected

        for mask in range(1 << ns):
            for cur in range(ns + 1):
                if dp[cur][mask] == INF: continue
                for nxt in range(1, ns + 1):
                    bit = nxt - 1
                    if mask & (1 << bit): continue
                    nmask = mask | (1 << bit)
                    cost = dp[cur][mask] + d(cur, nxt)
                    if cost < dp[nxt][nmask]:
                        dp[nxt][nmask] = cost

        full = (1 << ns) - 1
        ans = INF
        for cur in range(ns + 1):
            if dp[cur][full] < INF:
                ans = min(ans, dp[cur][full] + d(cur, ns + 1))

        print(ans)

solve()

import sys
import heapq

def solve():
    input = sys.stdin.readline
    H, W = map(int, input().split())
    grid = [list(input().rstrip('\n')) for _ in range(H)]

    points = []  # start, scrolls..., goal
    start = goal = None
    scrolls = []

    holes = []
    for i in range(H):
        for j in range(W):
            c = grid[i][j]
            if c == 'S':
                start = (i, j)
            elif c == 'G':
                goal = (i, j)
            elif c == '*':
                scrolls.append((i, j))
            elif c == 'X':
                holes.append((i, j))

    points = [start] + scrolls + [goal]
    n_scrolls = len(scrolls)
    P = len(points)

    # Cost to enter each cell:
    # impassable: hole 'X'
    # otherwise 1 + number of adjacent holes
    enter_cost = [[10**18] * W for _ in range(H)]
    dirs = [(-1,0),(1,0),(0,-1),(0,1)]

    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'X':
                continue
            cnt = 0
            for di, dj in dirs:
                ni, nj = i + di, j + dj
                if 0 <= ni < H and 0 <= nj < W and grid[ni][nj] == 'X':
                    cnt += 1
            enter_cost[i][j] = 1 + cnt

    def dijkstra(sr, sc):
        INF = 10**18
        dist = [[INF] * W for _ in range(H)]
        pq = [(0, sr, sc)]
        dist[sr][sc] = 0
        while pq:
            d, r, c = heapq.heappop(pq)
            if d != dist[r][c]:
                continue
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if not (0 <= nr < H and 0 <= nc < W):
                    continue
                if grid[nr][nc] == 'X':
                    continue
                nd = d + enter_cost[nr][nc]
                if nd < dist[nr][nc]:
                    dist[nr][nc] = nd
                    heapq.heappush(pq, (nd, nr, nc))
        return dist

    # Pairwise shortest paths among important points
    pair = [[10**18] * P for _ in range(P)]
    all_dist = []
    for idx, (r, c) in enumerate(points):
        dist = dijkstra(r, c)
        all_dist.append(dist)
        for jdx, (rr, cc) in enumerate(points):
            pair[idx][jdx] = dist[rr][cc]

    INF = 10**18

    # If no scrolls: just S -> G
    if n_scrolls == 0:
        ans = pair[0][1]
        print(-1 if ans >= INF else ans)
        return

    # TSP-like DP:
    # point indices: 0=S, 1..n_scrolls=scrolls, n_scrolls+1=G
    full = 1 << n_scrolls
    dp = [[INF] * n_scrolls for _ in range(full)]

    for i in range(n_scrolls):
        d = pair[0][1 + i]
        if d < INF:
            dp[1 << i][i] = d

    for mask in range(full):
        for last in range(n_scrolls):
            cur = dp[mask][last]
            if cur >= INF:
                continue
            for nxt in range(n_scrolls):
                if (mask >> nxt) & 1:
                    continue
                d = pair[1 + last][1 + nxt]
                if d >= INF:
                    continue
                nmask = mask | (1 << nxt)
                nd = cur + d
                if nd < dp[nmask][nxt]:
                    dp[nmask][nxt] = nd

    ans = INF
    final_mask = full - 1
    for last in range(n_scrolls):
        cur = dp[final_mask][last]
        if cur >= INF:
            continue
        d = pair[1 + last][n_scrolls + 1]
        if d < INF:
            ans = min(ans, cur + d)

    print(-1 if ans >= INF else ans)

if __name__ == "__main__":
    solve()
